"""Self-contained report styles; opaque surfaces remain readable without blur."""

from wtjudge.presentation import STATUS_COLOURS

REPORT_CSS = """
:root{color-scheme:light;--ink:#27312c;--muted:#89918c;--green:#557e35;--line:#e7ebe7;--soft:#edf3e8}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#e9edf0;font:14px/1.6 "Segoe UI","Microsoft YaHei UI",sans-serif;color:var(--ink)}
body:before{content:"";position:fixed;inset:0;z-index:-1;background:radial-gradient(ellipse at 96% 0%,#e6eedf 0,transparent 48%),radial-gradient(ellipse at 0% 100%,#e3e9df 0,transparent 42%)}
a{color:inherit;text-decoration:none}.shell{display:grid;grid-template-columns:174px minmax(0,1fr);max-width:1440px;min-height:calc(100vh - 48px);margin:24px auto;border:1px solid #ffffff;border-radius:25px;overflow:hidden;background:rgba(250,252,252,.86);box-shadow:0 18px 65px #43524612;backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px)}
.sidebar{background:rgba(255,255,255,.68);border-right:1px solid #e7ece780;padding:28px 18px}.brand{display:flex;align-items:center;gap:10px;font-size:20px;font-weight:650;letter-spacing:-.5px;color:#456b2f}.brand img{width:32px;height:32px;object-fit:contain}.brand-mark{display:grid;place-items:center;width:32px;height:32px;border-radius:11px;background:#edf3e7;color:#527c33;font-size:23px}
nav{display:grid;gap:7px;margin-top:50px}nav a{padding:10px 14px;border-radius:9px;font-size:13px;color:#849087}nav a:first-child{background:#edf4e7;color:#4d7631;font-weight:600}nav a:hover{background:#f0f4ed;color:#4d7631}.nav-number{display:inline-block;width:24px;font-size:11px;opacity:.6}
main{padding:30px 34px 22px;min-width:0}.topline{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:27px}h1{font-size:25px;line-height:1.3;font-weight:600;letter-spacing:-.5px;margin:0 0 7px}h2{font-size:17px;font-weight:600;margin:0}p{margin:0}.subline{color:var(--muted);font-size:12px}.completion{display:inline-flex;align-items:center;gap:7px;border:1px solid #deead8;border-radius:100px;padding:5px 12px;background:#f3f8ee;color:#62834b;font-size:12px;white-space:nowrap}.completion:before{content:"";width:6px;height:6px;border-radius:50%;background:#7ba451}.completion.partial{background:#fff7ed;border-color:#f1dfc3;color:#a77a42}.completion.partial:before{background:#c4985e}
.surface{background:rgba(255,255,255,.77);border:1px solid #ffffff;border-radius:15px;box-shadow:0 6px 24px #394b3710;overflow:hidden;margin-bottom:24px}.section-bar{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:19px 22px 15px}.search{background:#f8faf8;border:1px solid #e9ede8;border-radius:9px;padding:9px 12px;width:230px;outline:none;font:inherit;font-size:12px;color:var(--ink)}.search:focus{border-color:#a7bb97;box-shadow:0 0 0 3px #cedfc32e}.search::placeholder{color:#a2aaa4}
.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}th,td{text-align:left;padding:14px 16px;border-bottom:1px solid #edf0eb;vertical-align:middle}th{font-size:11px;font-weight:500;color:#929c93;white-space:nowrap;background:#fafcf9}td{font-size:13px}tbody tr:last-child td{border-bottom:0}tbody tr:hover{background:#f8fbf6}.numeric{text-align:center;white-space:nowrap}.rank{color:#a7afa7;width:54px;text-align:center}.student{font-weight:500;white-space:nowrap}.student a:hover{color:var(--green)}.score{font-weight:550}.score .cell-note{display:block;color:#a1a8a0;font-size:10px;font-weight:400;line-height:1.3;white-space:nowrap}.score.high{color:#5c843a}.score.low{color:#a7afa7}.score.invalid{color:#ba8053}.total{font-weight:650;color:#3f642d}.row-state{color:#97a28f;font-size:11px;white-space:nowrap}.row-state.incomplete{color:#b68b59}.coverage{font-size:11px;color:#9ba49b;padding:10px 22px 13px;border-top:1px solid #eff2ec}.empty{color:#9ba49b;padding:20px;text-align:center}.warning{background:#fff6eb;border:1px solid #f0dfc9;color:#a17238;padding:12px 16px;margin:0 0 16px;border-radius:11px;font-size:12px;overflow-wrap:anywhere}.warning strong{display:block;font-weight:600;margin-bottom:3px}
.details-heading{display:flex;align-items:baseline;justify-content:space-between;padding:2px 2px 12px}.details-heading span{font-size:11px;color:#9ba49b}.student-detail{background:rgba(255,255,255,.71);border:1px solid #ffffff;border-radius:12px;box-shadow:0 3px 15px #394b3708;margin-bottom:9px;overflow:hidden}.student-detail>summary{display:flex;align-items:center;justify-content:space-between;cursor:pointer;list-style:none;padding:14px 19px;font-weight:500;font-size:13px}.student-detail>summary::-webkit-details-marker{display:none}.student-detail>summary:after{content:"+";font-size:16px;color:#98a68e;font-weight:300;margin-left:16px}.student-detail[open]>summary:after{content:"−"}.detail-stats{margin-left:auto;color:#a5ada0;font-weight:400;font-size:11px}.detail-inner{padding:0 14px 14px}.point-table th{padding:10px;font-size:10px}.point-table td{padding:9px 10px;font-size:12px}.point-table .message{min-width:150px;max-width:400px}.verdict{display:inline-block;border-radius:5px;padding:2px 7px;font-size:10px;font-weight:550;letter-spacing:.3px;background:#eef1ed;color:#889185;white-space:nowrap}.verdict.ac{background:#edf4e7;color:#6f8e50}.verdict.wa{background:#fbefea;color:#b58a76}.verdict.tle,.verdict.mle,.verdict.output_limit{background:#fcf4e5;color:#af9663}.verdict.ce{background:#f2edf6;color:#9b88ab}.verdict.re,.verdict.no_output{background:#fbefea;color:#b58a76}.verdict.system_error,.verdict.cancelled,.verdict.ambiguous_source{background:#fff2df;color:#ae8753}.diagnostic{font-size:11px}.diagnostic summary{cursor:pointer;color:#9da694;white-space:nowrap}.diagnostic pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:260px;overflow:auto;font:11px/1.65 Consolas,"Microsoft YaHei UI",monospace;background:#f6f8f4;padding:10px;border-radius:7px;color:#727e6b;margin:7px 0 0}.method{margin-top:23px;color:#a0a99d;font-size:11px}.method summary{cursor:pointer;display:inline-block}.method p{padding:8px 0;max-width:750px}.visually-hidden{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}[hidden]{display:none!important}
@media(max-width:1500px){.shell{margin:18px;min-height:calc(100vh - 36px)}}@media(max-width:850px){.shell{display:block;margin:10px;border-radius:17px}.sidebar{display:flex;justify-content:space-between;align-items:center;padding:15px 20px;border-right:0;border-bottom:1px solid var(--line)}nav{display:flex;margin:0;gap:4px}nav a{padding:6px 10px}.nav-number{display:none}main{padding:24px 18px}.topline{margin-bottom:20px}.section-bar{padding:15px}.search{width:180px}th,td{padding:12px}h1{font-size:22px}}
@media(max-width:530px){.sidebar nav a:not(:first-child){display:none}.topline{display:block}.completion{margin-top:10px}.section-bar{align-items:flex-start;flex-direction:column;gap:12px}.search{width:100%}.detail-stats{display:none}.coverage{padding:10px 15px}.student-detail>summary{padding:12px 15px}}
@media print{body{background:#fff}.shell{display:block;margin:0;border:0;box-shadow:none;backdrop-filter:none;background:#fff}.sidebar,.search,nav,.method{display:none}main{padding:0}.surface,.student-detail{box-shadow:none;border:1px solid #e5e9e2}a{color:inherit}.topline{margin-bottom:15px}}
"""

# Keep the report's verdicts identical to the desktop and spreadsheet colours.
REPORT_CSS += "\n" + "\n".join(
    f".verdict.{status.lower()}{{background:{background};color:{foreground}}}"
    for status, (background, foreground) in STATUS_COLOURS.items()
)
REPORT_CSS += """
.score,.total{color:#16221b;border-left:1px solid #ffffff80}
.score.uniform-error{font-weight:650;letter-spacing:.25px}
.verdict{font-weight:650;padding:3px 9px;font-size:11px}
@media print{*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
"""
